class QuarryInput extends "res://tests/helpers/gate_a_material_route.gd":
	var walk: Callable

	func _equip(item_id: String) -> bool:
		# The original gather helper addresses tools by material; rootstone uses
		# the same real pickaxe/hotbar/visible-held-prop input path as stone.
		return await super._equip("stone" if item_id == "rootstone" else item_id)

	# The gather helper's own walks are best effort: `_stand_where_it_wins`
	# tries up to ten stand points round a node and moves on from any it
	# cannot reach. Seed 15 (run 36268640030) failed the whole route because
	# its first point, behind a choppable tree 1 m from the rootstone, timed
	# out through the segment's fatal `_walk`. A player tries another side.
	func _walk_to(target: Vector3, close_enough: float, budget: int, headings: Array[Vector3] = []) -> bool:
		# Keep the parent's guided legs when a gather target needs them; each
		# leg still uses this segment's fight-aware, best-effort walk.
		var started := Engine.get_physics_frames()
		for heading: Vector3 in headings:
			var remaining := budget - (Engine.get_physics_frames() - started)
			if remaining <= 0 or not await walk.call(heading, 2.5, remaining, true):
				return false
		budget -= Engine.get_physics_frames() - started
		if budget <= 0: return false
		return await walk.call(target, close_enough, budget, true)


class WalkSession extends RefCounted:
	var anchor: Vector3
	var anchor_age := 0

	func _init(at: Vector3) -> void:
		reset(at)

	func reset(at: Vector3) -> void:
		anchor = at
		anchor_age = 0

	func step(navigator: RefCounted, at: Vector3, target: Vector3) -> bool:
		# This interleaved walk cannot use NAV.walk_to: the caller must still
		# observe and pilot each real fight. Retain that walk's leg watchdog,
		# which raw NAV.step lacks. The retained quarry run walked 80m inside
		# a roughly 4m pocket against Foundation_0 without ever noticing.
		var confined := false
		if at.distance_to(anchor) > NAV.CONFINED_RADIUS_M:
			reset(at)
		else:
			anchor_age += 1
			if anchor_age >= NAV.CONFINED_FRAMES:
				var to := target - at
				to.y = 0.0
				navigator.reset()
				navigator._back_off(to)
				reset(at)
				confined = true
		navigator.step(target)
		return confined


