func _travel() -> bool:
	var stops := rootstone_stops(_read(HARVEST))
	var terrain := _read(TERRAIN)
	var road := trail_points(terrain, "bands", "band2_stone_and_root")
	var undertrail := trail_points(terrain, "loops", "warren_undertrail")
	var chambers := passage_path(_config, "mouth", str((_config.get("guardian", {}) as Dictionary).get("chamber", "")))
	if stops.is_empty() or road.is_empty() or undertrail.is_empty() or chambers.is_empty():
		return _fail("Current authored quarry, Band2 trail or ungated guardian route is absent")
	var quarry_centre := Vector2.ZERO
	for row: Dictionary in stops:
		quarry_centre += _v2(row.at)
	quarry_centre /= float(stops.size())
	var quarry_join := nearest_index(road, quarry_centre)
	var warren_join := nearest_index(road, undertrail[0])
	if quarry_join < 0 or warren_join <= quarry_join:
		return _fail("The current trail no longer places the quarry before the Warrens approach")
	if not await _prepare():
		return false
	# Up the trail to the vertex before the quarry's; the nodes are walked to
	# from there (the quarry vertex itself stands in the station's props).
	for index in range(quarry_join):
		if not await _walk_ground(road[index]):
			return false
	var gather := QuarryInput.new()
	gather._tree = _tree
	gather._world = _world
	gather._game = _game
	gather._player = _player
	gather._rig = _rig
	gather._arbiter = _arbiter
	gather.walk = _walk
	if not gather._resolve_move_bindings():
		return _fail("The carried pickaxe route lacks its actual controller movement binding")
	gather._nav = NAV.new(_tree, _player, _rig, gather._send_stick)
	for row: Dictionary in stops:
		var at := _v2(row.at)
		# HarvestNode's production prompt is configured at 2.4m. Requiring a
		# 1.5m centre approach first adds a stricter, non-gameplay collision
		# gate; 2.2m gets the real prompt/arbiter check its intended turn.
		if not await _via_haul_apron(at) or not await _around_station(_v2p(), at) \
				or not await _walk_ground(at, 2.2):
			return false
		var node := gather._authored_node_at(at, "rootstone")
		if node == null:
			return _fail("No unspent authored quarry rootstone at " + str(at))
		var node_id := node.get_instance_id()
		var amount := int(node.call("resource_amount"))
		if amount != int(row.amount):
			return _fail("The live rootstone node does not expose its configured remaining amount")
		var expected := int((_game.get("items") as RefCounted).call("harvest_yield", "rootstone", amount, true, false))
		var before := _count("rootstone")
		if not await gather._harvest_node(node, "rootstone", true):
			return _fail("Actual pickaxe/rootstone input failed: " + str(gather.failures))
		if expected <= 0 or _count("rootstone") - before != expected or not _failures.is_empty():
			return _fail("The actual quarry swing did not yield the configured carried rootstone amount")
		_receipt("quarry_rootstone", {"at": at, "node_id": node_id, "yield": expected,
			"before": before, "after": _count("rootstone")})
	# On along the trail from the last node, not back through its quarry vertex:
	# that vertex stands inside the station's props (barrel, bucket, bag,
	# signpost and a rock within 1 m of it) and the walker was boxed in there
	# twice (seed 15, 2026-09-26). A player walks round them; so does this.
	if not await _around_station(_v2p(), road[quarry_join + 1]):
		return false
	for index in range(quarry_join + 1, warren_join + 1):
		if not await _walk_ground(road[index]):
			return false
	var available: Array = _warrens.call("chamber_ids")
	for chamber: String in chambers:
		if not available.has(chamber):
			return _fail("The loaded cave is missing authored chamber " + chamber)
	var entrance: Vector3 = _warrens.call("marker", "entrance")
	var mouth: Vector3 = _warrens.call("marker", "mouth")
	var outside := outside_approach(entrance, mouth, staging_run(_warrens, _config, entrance))
	if outside == Vector3.INF:
		return _fail("The live entrance has no usable mouth direction or authored apron")
	for index in range(nearest_index(undertrail, Vector2(outside.x, outside.z)) + 1):
		if not await _around("spike_bypass", SPIKE_KNOT, SPIKE_CLEAR_M, SPIKE_BYPASS, _v2p(), undertrail[index]) \
				or not await _walk_ground(undertrail[index]):
			return false
	# This is a staging pose outside the authored mouth, not an interaction.
	# Ordinary wild detours can finish against the bank about 4.2 m from this
	# computed point while already standing on the same clear approach apron.
	# Keep the cave entrance, guardian admission and every prompt exact; this
	# wider tolerance applies only to the non-interactive preparation checkpoint.
	if not await _walk_staging(Vector2(outside.x, outside.z)) or not await _prepare():
		return false
	# The staging radius is flat; a fight on the approach can leave the player
	# up on the earth bank over the mouth, inside that radius but 3 m above the
	# apron (seed 15, bade6d57: stuck at y 7.4 over an entrance at y 4.1). Step
	# back out along the approach onto the apron before walking in.
	if not await _off_the_bank(entrance, mouth, outside):
		return false
	# Line up with the ramp before climbing it: the flat staging tolerance can
	# leave the trainer metres off the mouth axis, and a straight leg from
	# there crosses the ramp's sheer side (walk probe, 13 Oct: entombed beside
	# it at y 5.0). From the axis point at its foot the leg runs up the ramp.
	if not await _walk_ground(Vector2(outside.x, outside.z), RAMP_AXIS_RADIUS_M):
		return false
	_allow_guardian = true
	# Use marker Y underground. Terrain height there describes the bank above
	# the room, and projecting a chamber back to that surface would walk the roof.
	if not await _walk(entrance):
		return false
	var previous: Vector3 = entrance
	for chamber: String in chambers:
		var marker: Vector3 = _warrens.call("marker", chamber)
		if not await _chamber_leg(previous, marker):
			return false
		previous = marker
	if _guardian_wins == 0:
		if not await _engage_guardian() or not await _fight():
			return false
	if not _guardian_verified:
		return _fail("The guardian victory never produced a complete immediate reward receipt")
	for index in range(chambers.size() - 2, -1, -1):
		var marker: Vector3 = _warrens.call("marker", chambers[index])
		if not await _chamber_leg(previous, marker):
			return false
		previous = marker
	if not await _chamber_leg(previous, entrance) or not await _walk_staging(Vector2(outside.x, outside.z)):
		return false
	if not retained_five(_initial_ids, _party_ids()) or _tree.current_scene != _world \
			or str(_game.get("current_realm")) != "meadows" or _fighting():
		return _fail("The same five earned creatures did not leave the cave in the same world")
	_receipt("warrens_exited", {"player": _player.global_position, "entrance": entrance,
		"outside": outside, "party_ids": _party_ids()})
	return true


## The quarry station's props, the OldQuarry foundation and its TetherConduits
## box fill x 394-407, z 1798-1807 round the trail's quarry vertex (a 0.45 m
## sphere cast on a 1 m grid, 2026-09-26); x 408 and east is open. A leg whose
## straight line passes within STATION_CLEAR_M of that knot goes round its east
## side. (A single bypass point at (404.5,1804.5) sat on the conduit box.)
const STATION_KNOT := Vector2(401.0, 1802.5)
const STATION_CLEAR_M := 5.0
const STATION_BYPASS: Array[Vector2] = [Vector2(405.0, 1796.8), Vector2(409.5, 1797.0), Vector2(409.5, 1808.5)]
## The undertrail's first leg, (-420,2470) -> (-380,2540), runs over a rock
## spike near (-400,2500) that stands ~7 m above the ground either side of it
## (ground_height_at grid, 2026-09-26); the walker stalled against it (seed 15).
## The valley west of it (x -410..-405, heights -4..-6) is open.
const SPIKE_KNOT := Vector2(-400.0, 2500.0)
const SPIKE_CLEAR_M := 6.0
const SPIKE_BYPASS: Array[Vector2] = [Vector2(-409.0, 2512.0)]


const BANK_RISE_M := 1.5
## The Old Quarry's worked faces stand as one 4-6 m wall along z 1789-1794
## (data/config/old_quarry.json worked_cut, x 375-396); nodes on the upper
## bench behind it are reached up the haul apron on the east side
## (HaulApronUpper, ConduitApronInner, the 12 m upper apron at (400,1799.5)).
## Walking straight from the road below met the face three times (seed 15:
## CI r15, r17 and a resume dry run, stuck near (360-371,1752-1772)).
const QUARRY_CUT_Z := 1789.0
const QUARRY_HAUL_VIA: Array[Vector2] = [Vector2(398.0, 1783.0), Vector2(400.0, 1794.0)]


func _via_haul_apron(target: Vector2) -> bool:
	if not needs_haul_apron(_v2p(), target):
		return true
	_receipt("quarry_haul_apron", {"from": _v2p(), "to": target})
	for via: Vector2 in QUARRY_HAUL_VIA:
		if not await _walk_ground(via, 2.0):
			return false
	return true


static func needs_haul_apron(from: Vector2, to: Vector2) -> bool:
	return from.y < QUARRY_CUT_Z and to.y > QUARRY_CUT_Z and to.x > 370.0 and to.x < 420.0 \
		and from.x > 330.0 and from.x < 420.0
const GO_AROUND_M := 10.0
var _going_around := false
const MAX_WILD_LOSSES := 3
var _wild_losses := 0


## One leg between authored chamber markers. A wild fight inside the cave can
## leave the player off the passage line, where the straight leg is confined
## by the walls (seed 15 resume dry run, 21420e92: 14.5 m short of the next
## marker after a fight). A player backs up to the last room they stood in
## and goes on from there; so does this, once, before the leg fails.
func _chamber_leg(from: Vector3, to: Vector3) -> bool:
	if await _walk(to, 1.5, -1, true):
		return true
	if not _failures.is_empty():
		return false
	_receipt("chamber_leg_retrace", {"player": _player.global_position, "back_to": from, "target": to})
	if not await _walk(from, 1.5, -1, true) and not _failures.is_empty():
		return false
	return await _walk(to)


func _off_the_bank(entrance: Vector3, mouth: Vector3, outside: Vector3) -> bool:
	var apron_y := float(_world.call("ground_height_at", outside.x, outside.z))
	if not on_the_bank(_player.global_position.y, apron_y):
		return true
	var further := outside_approach(entrance, mouth, staging_run(_warrens, _config, entrance) + 6.0)
	_receipt("off_the_bank", {"player": _player.global_position, "apron_y": apron_y, "via": further})
	if further == Vector3.INF or not await _walk_ground(Vector2(further.x, further.z)) \
			or not await _walk_ground(Vector2(outside.x, outside.z)):
		return false
	if on_the_bank(_player.global_position.y, apron_y):
		return _fail("Still above the Warrens apron after stepping back out: player=%s apron_y=%.2f" % [_player.global_position, apron_y])
	return true


static func on_the_bank(player_y: float, apron_y: float) -> bool:
	return player_y - apron_y > BANK_RISE_M


func _around_station(from: Vector2, to: Vector2) -> bool:
	return await _around("station_bypass", STATION_KNOT, STATION_CLEAR_M, STATION_BYPASS, from, to)


## Walks the `via` points in order first when the straight leg from -> to passes within `clear` of `knot`. Ordinary movement
## input either way; only the line is chosen.
func _around(beat: String, knot: Vector2, clear: float, via: Array[Vector2], from: Vector2, to: Vector2) -> bool:
	if Geometry2D.get_closest_point_to_segment(knot, from, to).distance_to(knot) >= clear:
		return true
	_receipt(beat, {"from": from, "to": to, "via": via})
	for point: Vector2 in via:
		if from.distance_to(point) < 1.5 or to.distance_to(point) < 1.5:
			continue
		if not await _walk_ground(point):
			return false
	return true


func _v2p() -> Vector2:
	return Vector2(_player.global_position.x, _player.global_position.z)


func _prepare() -> bool:
	# Bind only the existing care/selection seam, never the opening/team run.
	# A wild that engages while the Satchel is being reached is fought first,
	# as a player would (F19#5 sigils, a2229779: refused with fighting true);
	# the care itself is retried whole and must still succeed.
	var care: RefCounted
	for attempt in 3:
		if _fighting():
			_receipt("care_interrupted_by_wild", {"attempt": attempt, "party": _party_hp()})
			if not await _fight():
				return false
		care = CARE.new()
		care._tree = _tree
		care._world = _world
		care._game = _game
		care._menu = _game.call("menu")
		if await care._prepare_pilot(false):
			break
		if not _fighting() or attempt == 2:
			return _fail("Earned Satchel preparation failed: " + str(care.result().failures))
	if _director.call("ally_body") == null:
		await _input._tap("creature_recall")
	for _frame in 180:
		if str(_director.call("usable_ally_blocker")).is_empty():
			return true
		await _tree.physics_frame
	return _fail("Actual care, party selection and deployment left no usable ally")


## Before a named trainer (relay captain, Sigil captains, Hall gauntlet) a
## player tops the whole team up, not only the lead: seed 15 (5152b44a) lost
## stronghold_elite with two fainted and the rest at 23-48 HP while carrying
## seven small potions. Revive and pilot as `_prepare` does, then carried
## potions on every member under TOP_UP_BELOW while the stock lasts.
const TOP_UP_BELOW := 0.6


func _prepare_for_trainer() -> bool:
	if not await _prepare():
		return false
	var care := CARE.new()
	care._tree = _tree
	care._world = _world
	care._game = _game
	care._menu = _game.call("menu")
	var party := _game.get("party") as RefCounted
	var inventory := _game.get("inventory") as RefCounted
	for index in int(party.call("size")):
		var member: RefCounted = party.call("at", index)
		while member != null and not bool(member.get("fainted")) \
				and float(member.get("hp")) < float(member.get("max_hp")) * TOP_UP_BELOW \
				and int(inventory.call("count", "potion_small")) > 0:
			if not await care._use_remedy("potion_small", index):
				return _fail("Pre-trainer Satchel top-up failed: " + str(care.result().failures))
	_receipt("trainer_top_up", {"party": _party_hp(), "potions_left": int(inventory.call("count", "potion_small"))})
	var spec: Variant = get("_captain_spec")
	if spec is Dictionary and not (spec as Dictionary).is_empty():
		var room := CARE.new()
		room._tree = _tree
		room._world = _world
		room._game = _game
		room._menu = _game.call("menu")
		if not await room.free_slots_for(((spec as Dictionary).get("reward", {}) as Dictionary).get("items", [])):
			return _fail("Pre-captain Satchel room failed: " + str(room.result().failures))
		for row: Variant in (room.result().get("receipts", []) as Array):
			if row is Dictionary and str((row as Dictionary).get("beat", "")) == "satchel_room_dropped":
				_receipt("satchel_room_dropped", row)
	return true


## Wild fights on a long walk wear the five down; with no care between them
## seed 15 lost an L15 wild on the Hall spine with four of five fainted and ten
## revives carried. After a win, a fainted member or a lead under half health
## sends the walker through the same Satchel care `_prepare` runs at each
## segment's start (revive, potion, pilot), as a player would.
const CARE_BELOW := 0.5


func _needs_care() -> bool:
	var party := _game.get("party") as RefCounted
	var active: RefCounted = party.call("at", int(party.call("active_index")))
	for member: RefCounted in (_game.get("party") as RefCounted).call("members"):
		if bool(member.get("fainted")):
			return true
	return active != null and float(active.get("hp")) < CARE_BELOW * float(active.get("max_hp"))


func _party_hp() -> Array:
	var out := []
	for member: RefCounted in (_game.get("party") as RefCounted).call("members"):
		out.append("L%d %.0f/%.0f%s" % [int(member.get("level")), float(member.get("hp")),
			float(member.get("max_hp")), " fainted" if bool(member.get("fainted")) else ""])
	return out


func _walk_staging(at: Vector2) -> bool:
	_flat_arrival = true
	var arrived: bool = await _walk_ground(at, OUTSIDE_STAGING_FLAT_RADIUS)
	_flat_arrival = false
	return arrived


func _walk_ground(at: Vector2, radius: float = 1.5) -> bool:
	return await _walk(Vector3(at.x, float(_world.call("ground_height_at", at.x, at.y)), at.y), radius)


func _walk(target: Vector3, radius: float = 1.5, budget: int = -1, best_effort := false) -> bool:
	if budget < 0:
		budget = maxi(1800, int(_player.global_position.distance_to(target) / 2.5 * 60.0) + 600)
	_nav.reset()
	var session := WalkSession.new(_player.global_position)
	var last_recovery := Vector3.INF
	var sidestep_sign := 1.0
	for _frame in budget:
		if not _failures.is_empty():
			return false
		if _fighting():
			_stick(0.0, 0.0)
			if not await _fight():
				return false
			if _needs_care():
				_receipt("care_between_fights", {"party": _party_hp()})
				if not await _prepare():
					return false
			_nav.reset()
			session.reset(_player.global_position)
		if INPUT_OWNER.current(_tree) != null:
			_stick(0.0, 0.0)
			return _fail("Unexpected modal interrupted the real quarry/Warrens walk")
		var gap := Vector2(_player.global_position.x - target.x, _player.global_position.z - target.z).length() \
			if _flat_arrival else _player.global_position.distance_to(target)
		if gap <= radius:
			_stick(0.0, 0.0)
			return true
		var at := _player.global_position
		if session.step(_nav, at, target):
			_receipt("walk_confined_recovery", {"player": at, "target": target})
			# A back-off that leaves the body where it was (seed 15: twice at
			# the same point on a rope collider between two rocks) will not
			# free it. Step aside across the heading, alternating sides, as a
			# player would, then resume this leg.
			if not _sidestepping and last_recovery != Vector3.INF and at.distance_to(last_recovery) < 1.0:
				var heading := target - at
				heading.y = 0.0
				var side := Vector3(-heading.z, 0.0, heading.x).normalized() * SIDESTEP_M * sidestep_sign
				sidestep_sign = -sidestep_sign
				var aside := Vector2(at.x + side.x, at.z + side.z)
				_receipt("walk_sidestep", {"player": at, "target": target, "aside": aside})
				_sidestepping = true
				await _walk(Vector3(aside.x, float(_world.call("ground_height_at", aside.x, aside.y)), aside.y), 1.5, SIDESTEP_FRAMES)
				_sidestepping = false
				if not _failures.is_empty():
					return false
				_nav.reset()
				session.reset(_player.global_position)
			last_recovery = at
		await _tree.physics_frame
	_stick(0.0, 0.0)
	if _sidestepping or best_effort:
		return false  # Best effort; the leg or stand search it serves resumes.
	# A route leg that ran out of budget gets one go-around before it fails:
	# ten metres to either side of the heading, then the target again, as a
	# player walks round whatever the straight line keeps meeting (CI r14/r15:
	# the quarry approach near (394,1797) and the relay exit toward (-152,4170)).
	if not _going_around:
		_going_around = true
		var at := _player.global_position
		var heading := target - at
		heading.y = 0.0
		var side := Vector3(-heading.z, 0.0, heading.x).normalized() * GO_AROUND_M
		for sign: float in [1.0, -1.0]:
			var aside := Vector2(at.x + side.x * sign, at.z + side.z * sign)
			_receipt("leg_go_around", {"player": at, "target": target, "aside": aside})
			await _walk(Vector3(aside.x, float(_world.call("ground_height_at", aside.x, aside.y)), aside.y), 1.5, SIDESTEP_FRAMES, true)
			if not _failures.is_empty():
				_going_around = false
				return false
			if await _walk(target, radius, -1, true):
				_going_around = false
				return true
			if not _failures.is_empty():
				_going_around = false
				return false
		_going_around = false
	return _fail("Ordinary quarry/Warrens movement did not reach %s; player=%s" % [target, _player.global_position])


func _engage_guardian() -> bool:
	_nav.reset()
	for _frame in ENGAGE_FRAMES:
		if _fighting():
			_stick(0.0, 0.0)
			return _combat.call("enemy") == _guardian_creature \
				or _fail("Another wild interrupted the guardian's explicit admission")
		if not is_instance_valid(_guardian) or not bool(_guardian.call("is_alive")):
			return _fail("The guardian went down without an observed fight")
		if _arbiter.call("winning_provider") == _director \
				and bool(_arbiter.call("winner").get("actionable", false)) \
				and _director.call("_engageable") == _guardian:
			_stick(0.0, 0.0)
			await _input._tap("interact")
			if _fighting():
				return _combat.call("enemy_body") == _guardian \
					or _fail("The actual admission replaced the exact offered guardian")
		_nav.step(_guardian.global_position)
		await _tree.physics_frame
	_stick(0.0, 0.0)
	return _fail("The exact living Warren Guardian never admitted an ordinary encounter")


func _fight() -> bool:
	if bool(_director.call("trainer_battle_active")) or _fight_enemy == null:
		return _fail("An unexpected trainer or unobserved encounter interrupted the Warrens route")
	var guardian_fight := _fight_enemy == _guardian_creature
	if guardian_fight and not _allow_guardian:
		return _fail("The guardian encounter began before the actual cave approach/preparation")
	var pilot := WildPilot.new(_tree, _combat, _director, _rig)
	pilot.use_switching = false
	pilot.switch_input = true
	while _fighting() and within_battle_deadline(Engine.get_physics_frames() - _fight_started):
		if _combat.call("enemy") != _fight_enemy or bool(_director.call("trainer_battle_active")):
			pilot._move_toward(Vector3.ZERO)
			return _fail("The admitted wild identity changed during the input fight")
		var ally := _director.call("ally_body") as Node3D
		var foe := _combat.call("enemy_body") as Node3D
		if is_instance_valid(ally) and is_instance_valid(foe):
			await pilot._act(ally, foe)
			pilot._move_toward(Vector3.ZERO)
		else:
			await _tree.physics_frame
	pilot._move_toward(Vector3.ZERO)
	# A lost ordinary wild fight on a long leg is a setback a player recovers
	# from (the lead faints, exploration resumes; the Satchel revives), not the
	# end of the route. Seed 15 resume dry run (680d1eea) lost one on the Hall
	# approach with the party worn down. The guardian and trainers stay exact.
	if not guardian_fight and not _fighting() and str(_combat.call("outcome")) == "lost" \
			and _wild_losses < MAX_WILD_LOSSES:
		_wild_losses += 1
		_receipt("wild_loss_recovered", {"number": _wild_losses, "hits": _fight_hits,
			"frames": Engine.get_physics_frames() - _fight_started, "party": _party_hp()})
		for _frame in 180:
			if INPUT_OWNER.current(_tree) == null:
				break
			await _tree.physics_frame
		return await _prepare()
	if not within_battle_deadline(Engine.get_physics_frames() - _fight_started) \
			or _fighting() or str(_combat.call("outcome")) != "won" or _fight_hits <= 0:
		var party_hp := []
		for member: RefCounted in (_game.get("party") as RefCounted).call("members"):
			party_hp.append("%s L%d %.0f%s" % [member.get("species"), int(member.get("level")),
				float(member.get("hp")), " fainted" if bool(member.get("fainted")) else ""])
		var foe: RefCounted = _fight_enemy
		return _fail("Real wild combat did not win with landed strikes inside its unchanged physics budget (outcome '%s', fighting %s, hits %d, frames %d, foe %s, party %s)" % [
			str(_combat.call("outcome")), _fighting(), _fight_hits, Engine.get_physics_frames() - _fight_started,
			"%s L%d %.0f" % [foe.get("species"), int(foe.get("level")), float(foe.get("hp"))] if foe != null else "none",
			party_hp])
	_receipt("wild_victory", {"guardian": guardian_fight, "hits": _fight_hits, "switches": pilot.voluntary_switches,
		"enemy_id": _fight_enemy.get_instance_id(), "frames": Engine.get_physics_frames() - _fight_started})
	# Close the reward window before resuming walking: another actual wild on
	# the way to the den centre must not be counted as this guardian's XP.
	if guardian_fight:
		_guardian_verified = await _verify_guardian_reward()
		if not _guardian_verified:
			return false
	for _frame in 120:
		if INPUT_OWNER.current(_tree) == null:
			return true
		await _tree.physics_frame
	return _fail("The actual wild victory did not release world input")


func _on_entered() -> void:
	_fight_started = Engine.get_physics_frames()
	_fight_enemy = _combat.call("enemy")
	_fight_hits = 0
	if _fight_enemy == _guardian_creature:
		if not _guardian_before.is_empty() or _combat.call("enemy_body") != _guardian:
			_fail("The guardian was readmitted or its body did not match the actual site guardian")
		else:
			_guardian_before = {"items": _reward_stock(), "xp": _xp_snapshot(),
				"xp_caps": xp_cap_snapshot((_game.get("party") as RefCounted).call("members"), PROGRESSION.config())}
			_receipt("guardian_admitted", {"body_id": _guardian.get_instance_id(),
				"creature_id": _guardian_creature.get_instance_id(), "before": _guardian_before.duplicate(true)})


func _on_hit(on_enemy: bool, _amount: float) -> void:
	if not on_enemy or _combat.call("enemy") != _fight_enemy:
		return
	_fight_hits += 1
	if _fight_enemy != _guardian_creature:
		return
	_guardian_hits += 1
	# Production emits the killing hit before ordinary victory XP. Snapshot
	# instance identities here; last_xp_award is keyed by duplicate labels.
	if float(_guardian_creature.get("hp")) <= 0.0 and _kill_active == 0:
		var active: RefCounted = _combat.call("active_creature")
		_kill_active = active.get_instance_id()
		for member: RefCounted in (_game.get("party") as RefCounted).call("members"):
			if not bool(member.get("fainted")):
				_kill_survivors.append(member.get_instance_id())


func _on_exit(outcome: String) -> void:
	if _fight_enemy == _guardian_creature and outcome == "won":
		_guardian_wins += 1


func _verify_guardian_reward() -> bool:
	for _frame in 120:
		if _has(_clear_flag()):
			break
		await _tree.physics_frame
	var reward: Dictionary = (_config.get("clear", {}) as Dictionary).get("reward", {})
	if _guardian_wins != 1 or _guardian_hits <= 0 or _guardian_before.is_empty() \
			or float(_guardian_creature.get("hp")) > 0.0 or not _has(_clear_flag()) \
			or not bool(_warrens.call("is_cleared")) or not retained_five(_initial_ids, _party_ids()) \
			or not exact_item_reward(_guardian_before.items, _reward_stock(), reward) \
			or not exact_xp_reward(_guardian_before.xp, _xp_snapshot(), _kill_active,
				_kill_survivors, int(_guardian_creature.get("level")), int(reward.get("xp_bonus", 0)), PROGRESSION.config(), _guardian_before.xp_caps, ESSENCE.config()):
		return _fail("Guardian clear lacks exact observed victory, configured payout/XP and retained-five receipts; before=%s after_items=%s after_xp=%s" % [
			_guardian_before, _reward_stock(), _xp_snapshot()])
	_receipt("warrens_cleared", {"hits": _guardian_hits, "wins": _guardian_wins,
		"items_before": _guardian_before.items, "items_after": _reward_stock(),
		"xp_before": _guardian_before.xp, "xp_after": _xp_snapshot(), "kill_active": _kill_active,
		"survivors": _kill_survivors, "party_ids": _party_ids()})
	return true


static func rootstone_stops(config: Dictionary) -> Array[Dictionary]:
	var rows: Array[Dictionary] = []
	for row: Dictionary in config.get("nodes", []):
		if str(row.get("item", "")) == "rootstone" and int(row.get("amount", 0)) > 0 \
				and (row.get("at", []) as Array).size() == 2:
			rows.append(row)
	rows.sort_custom(func(a: Dictionary, b: Dictionary) -> bool: return int(a.order) < int(b.order))
	return rows


static func trail_points(config: Dictionary, collection: String, id: String) -> Array[Vector2]:
	var points: Array[Vector2] = []
	for row: Dictionary in (config.get("trail", {}) as Dictionary).get(collection, []):
		if str(row.get("id", "")) == id:
			for raw: Array in row.get("points", []):
				points.append(_v2(raw))
	return points


static func nearest_index(points: Array[Vector2], target: Vector2) -> int:
	var index := -1
	var distance := INF
	for candidate in points.size():
		if points[candidate].distance_squared_to(target) < distance:
			distance = points[candidate].distance_squared_to(target)
			index = candidate
	return index


static func passage_path(config: Dictionary, start: String, goal: String) -> Array[String]:
	var queue: Array[Array] = [[start]]
	var visited: Array[String] = [start]
	while not queue.is_empty():
		var path: Array = queue.pop_front()
		var current := str(path[-1])
		if current == goal:
			var answer: Array[String] = []
			answer.assign(path)
			return answer
		for edge: Dictionary in config.get("passages", []):
			if bool(edge.get("gated", false)):
				continue
			var next := ""
			if str(edge.get("from", "")) == current:
				next = str(edge.get("to", ""))
			elif str(edge.get("to", "")) == current:
				next = str(edge.get("from", ""))
			if next.is_empty() or visited.has(next):
				continue
			visited.append(next)
			queue.append(path + [next])
	return []


## Distance back from the entrance marker to the staging pose: the live
## ramp's foot (the product's own `_apron_run_m()` from the mouth's outer face)
## plus STAGING_PAST_RAMP_FOOT_M. Falls back to the authored `site.apron_run_m`
## when the live site does not expose its ramp.
static func staging_run(warrens: Node3D, config: Dictionary, entrance: Vector3) -> float:
	var authored := float((config.get("site", {}) as Dictionary).get("apron_run_m", 0.0))
	if warrens == null or not warrens.has_method("_apron_run_m") or not warrens.has_method("_mouth_outer_z"):
		return authored
	var face := warrens.to_global(Vector3(0.0, 0.0, float(warrens.call("_mouth_outer_z"))))
	var entrance_out := Vector2(entrance.x - face.x, entrance.z - face.z).length()
	return maxf(authored, float(warrens.call("_apron_run_m")) - entrance_out + STAGING_PAST_RAMP_FOOT_M)


static func outside_approach(entrance: Vector3, mouth: Vector3, apron: float) -> Vector3:
	var forward := mouth - entrance
	forward.y = 0.0
	if forward.length() < 0.01 or apron <= 0.0:
		return Vector3.INF
	return entrance - forward.normalized() * apron


static func reward_items(reward: Dictionary) -> Dictionary:
	var items := {"coin": int(reward.get("coins", 0))}
	for row: Dictionary in reward.get("items", []):
		var id := str(row.get("id", ""))
		items[id] = int(items.get(id, 0)) + int(row.get("count", 1))
	return items


static func exact_item_reward(before: Dictionary, after: Dictionary, reward: Dictionary) -> bool:
	var expected := reward_items(reward)
	if before.size() != expected.size() or after.size() != expected.size():
		return false
	for id: String in expected:
		if not before.has(id) or not after.has(id) or int(after[id]) - int(before[id]) != int(expected[id]):
			return false
	return true


static func total_xp(level: int, xp: int, cfg: Dictionary) -> int:
	var total := xp
	for completed_level in range(1, level):
		total += PROGRESSION.xp_to_next(completed_level, cfg)
	return total


static func exact_xp_reward(before: Dictionary, after: Dictionary, active: int,
		survivors: Array[int], enemy_level: int, bonus: int, cfg: Dictionary, caps: Dictionary,
		essence_cfg: Dictionary = {}) -> bool:
	if before.size() != 5 or after.size() != 5 or caps.size() != 5 or not before.has(active) or not survivors.has(active):
		return false
	var award := PROGRESSION.xp_award_for(enemy_level, cfg)
	var share := PROGRESSION.party_share(award, cfg)
	if essence_cfg.get("wild_victory_xp_mode", "ordinary") == "hybrid":
		award = PROGRESSION.scaled_combat_xp(enemy_level, cfg, essence_cfg)
		share = PROGRESSION.scaled_party_combat_xp(enemy_level, cfg, essence_cfg)
	for id: int in before:
		if not after.has(id) or not caps.has(id) or int(caps[id]) < 0:
			return false
		var expected := 0
		if survivors.has(id):
			expected = bonus + (award if id == active else share)
		# TRAINING §2: neither victory nor the clear bonus banks XP beyond the
		# admitted cap. Snapshot caps before combat; never infer them from the
		# observed payout, which would allow a missing reward to pass.
		var target := int(before[id]) + expected
		if survivors.has(id):
			target = maxi(int(before[id]), mini(target, int(caps[id])))
		if int(after[id]) != target:
			return false
	return true


static func xp_cap_snapshot(members: Array, cfg: Dictionary) -> Dictionary:
	var caps := {}
	for member: RefCounted in members:
		var cap := int(member.call("_admitted_level_cap", cfg))
		caps[member.get_instance_id()] = total_xp(cap, 0, cfg) if cap > 0 else -1
	return caps


static func retained_five(before: Array[int], after: Array[int]) -> bool:
	if before.size() != 5 or before != after:
		return false
	var unique := {}
	for id: int in before:
		unique[id] = true
	return unique.size() == 5


static func within_battle_deadline(elapsed: int) -> bool:
	return elapsed >= 0 and elapsed < BATTLE_FRAMES


static func _v2(raw: Array) -> Vector2:
	return Vector2(float(raw[0]), float(raw[1]))


static func _read(path: String) -> Dictionary:
	var parsed: Variant = JSON.parse_string(FileAccess.get_file_as_string(path))
	return parsed if parsed is Dictionary else {}


func _reward_stock() -> Dictionary:
